CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, external_id TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(source_id, external_id));
CREATE TABLE IF NOT EXISTS research_results (id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES topics(id), payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS draft_revisions (id TEXT PRIMARY KEY, draft_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision > 0), parent_revision_id TEXT REFERENCES draft_revisions(id), topic_id TEXT NOT NULL REFERENCES topics(id), content_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(draft_id, revision));
CREATE TABLE IF NOT EXISTS verification_reports (id TEXT PRIMARY KEY, draft_revision_id TEXT NOT NULL REFERENCES draft_revisions(id), research_result_id TEXT NOT NULL REFERENCES research_results(id), content_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS platform_artifacts (id TEXT PRIMARY KEY, draft_revision_id TEXT NOT NULL REFERENCES draft_revisions(id), platform TEXT NOT NULL CHECK(platform IN ('Facebook_Page','Facebook_Group','YouTube')), artifact_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS compliance_results (id TEXT PRIMARY KEY, artifact_id TEXT NOT NULL REFERENCES platform_artifacts(id), draft_revision_id TEXT NOT NULL REFERENCES draft_revisions(id), artifact_hash TEXT NOT NULL, passed INTEGER NOT NULL CHECK(passed IN (0,1)), payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS pipeline_runs (id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES topics(id), active_draft_revision_id TEXT REFERENCES draft_revisions(id), stage TEXT NOT NULL CHECK(stage IN ('Collected','Scored','Researched','Generated','Verified','ComplianceChecked','PendingApproval','Approved','Rejected')), work_status TEXT NOT NULL CHECK(work_status IN ('Ready','InProgress','RetryableBlocked','Unscored','InsufficientData','VerificationBlocked','ComplianceFailed','Rejected')), version INTEGER NOT NULL CHECK(version >= 0), create_idempotency_key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, pipeline_run_id TEXT NOT NULL REFERENCES pipeline_runs(id), draft_revision_id TEXT NOT NULL REFERENCES draft_revisions(id), content_hash TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS approval_artifacts (approval_id TEXT NOT NULL REFERENCES approvals(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), artifact_id TEXT NOT NULL REFERENCES platform_artifacts(id), artifact_hash TEXT NOT NULL, PRIMARY KEY(approval_id, ordinal), UNIQUE(approval_id, artifact_id));
CREATE TABLE IF NOT EXISTS pipeline_transitions (id TEXT PRIMARY KEY, pipeline_run_id TEXT NOT NULL REFERENCES pipeline_runs(id), from_stage TEXT NOT NULL, to_stage TEXT NOT NULL, from_status TEXT NOT NULL, to_status TEXT NOT NULL, idempotency_key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), result_run_payload TEXT NOT NULL CHECK(json_valid(result_run_payload)), UNIQUE(pipeline_run_id, idempotency_key));
CREATE TABLE IF NOT EXISTS deliveries (id TEXT PRIMARY KEY, approval_id TEXT NOT NULL REFERENCES approvals(id), artifact_id TEXT NOT NULL REFERENCES platform_artifacts(id), artifact_hash TEXT NOT NULL, platform TEXT NOT NULL CHECK(platform IN ('Facebook_Page','Facebook_Group','YouTube')), idempotency_key TEXT NOT NULL UNIQUE, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE INDEX IF NOT EXISTS idx_research_topic ON research_results(topic_id);
CREATE INDEX IF NOT EXISTS idx_draft_topic ON draft_revisions(topic_id);
CREATE INDEX IF NOT EXISTS idx_report_revision ON verification_reports(draft_revision_id);
CREATE INDEX IF NOT EXISTS idx_artifact_revision ON platform_artifacts(draft_revision_id);
CREATE INDEX IF NOT EXISTS idx_compliance_artifact ON compliance_results(artifact_id);
CREATE INDEX IF NOT EXISTS idx_transition_run ON pipeline_transitions(pipeline_run_id);
CREATE TRIGGER IF NOT EXISTS verify_report_hash BEFORE INSERT ON verification_reports WHEN NOT EXISTS (SELECT 1 FROM draft_revisions d WHERE d.id=NEW.draft_revision_id AND d.content_hash=NEW.content_hash) BEGIN SELECT RAISE(ABORT, 'verification report content hash mismatch'); END;
CREATE TRIGGER IF NOT EXISTS verify_compliance_binding BEFORE INSERT ON compliance_results WHEN NOT EXISTS (SELECT 1 FROM platform_artifacts a WHERE a.id=NEW.artifact_id AND a.draft_revision_id=NEW.draft_revision_id AND a.artifact_hash=NEW.artifact_hash) BEGIN SELECT RAISE(ABORT, 'compliance artifact binding mismatch'); END;
CREATE TRIGGER IF NOT EXISTS verify_active_revision_insert BEFORE INSERT ON pipeline_runs WHEN NEW.active_draft_revision_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM draft_revisions d WHERE d.id=NEW.active_draft_revision_id AND d.topic_id=NEW.topic_id) BEGIN SELECT RAISE(ABORT, 'active revision topic mismatch'); END;
CREATE TRIGGER IF NOT EXISTS verify_active_revision_update BEFORE UPDATE OF active_draft_revision_id,topic_id ON pipeline_runs WHEN NEW.active_draft_revision_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM draft_revisions d WHERE d.id=NEW.active_draft_revision_id AND d.topic_id=NEW.topic_id) BEGIN SELECT RAISE(ABORT, 'active revision topic mismatch'); END;
CREATE TRIGGER IF NOT EXISTS verify_approval_hash BEFORE INSERT ON approvals WHEN NOT EXISTS (SELECT 1 FROM draft_revisions d WHERE d.id=NEW.draft_revision_id AND d.content_hash=NEW.content_hash) BEGIN SELECT RAISE(ABORT, 'approval content hash mismatch'); END;
CREATE TRIGGER IF NOT EXISTS verify_approval_artifact BEFORE INSERT ON approval_artifacts WHEN NOT EXISTS (SELECT 1 FROM approvals p JOIN platform_artifacts a ON a.id=NEW.artifact_id WHERE p.id=NEW.approval_id AND p.draft_revision_id=a.draft_revision_id AND a.artifact_hash=NEW.artifact_hash) BEGIN SELECT RAISE(ABORT, 'approval artifact binding mismatch'); END;
CREATE TRIGGER IF NOT EXISTS verify_delivery_binding BEFORE INSERT ON deliveries WHEN NOT EXISTS (SELECT 1 FROM approval_artifacts aa JOIN platform_artifacts a ON a.id=aa.artifact_id WHERE aa.approval_id=NEW.approval_id AND aa.artifact_id=NEW.artifact_id AND aa.artifact_hash=NEW.artifact_hash AND a.platform=NEW.platform) BEGIN SELECT RAISE(ABORT, 'delivery approval binding mismatch'); END;
CREATE TRIGGER IF NOT EXISTS immutable_topics_update BEFORE UPDATE ON topics BEGIN SELECT RAISE(ABORT, 'topics are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_topics_delete BEFORE DELETE ON topics BEGIN SELECT RAISE(ABORT, 'topics are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_research_update BEFORE UPDATE ON research_results BEGIN SELECT RAISE(ABORT, 'research results are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_research_delete BEFORE DELETE ON research_results BEGIN SELECT RAISE(ABORT, 'research results are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_drafts_update BEFORE UPDATE ON draft_revisions BEGIN SELECT RAISE(ABORT, 'draft revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_drafts_delete BEFORE DELETE ON draft_revisions BEGIN SELECT RAISE(ABORT, 'draft revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_reports_update BEFORE UPDATE ON verification_reports BEGIN SELECT RAISE(ABORT, 'verification reports are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_reports_delete BEFORE DELETE ON verification_reports BEGIN SELECT RAISE(ABORT, 'verification reports are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_artifacts_update BEFORE UPDATE ON platform_artifacts BEGIN SELECT RAISE(ABORT, 'platform artifacts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_artifacts_delete BEFORE DELETE ON platform_artifacts BEGIN SELECT RAISE(ABORT, 'platform artifacts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_compliance_update BEFORE UPDATE ON compliance_results BEGIN SELECT RAISE(ABORT, 'compliance results are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_compliance_delete BEFORE DELETE ON compliance_results BEGIN SELECT RAISE(ABORT, 'compliance results are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_approvals_update BEFORE UPDATE ON approvals BEGIN SELECT RAISE(ABORT, 'approvals are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_approvals_delete BEFORE DELETE ON approvals BEGIN SELECT RAISE(ABORT, 'approvals are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_approval_artifacts_update BEFORE UPDATE ON approval_artifacts BEGIN SELECT RAISE(ABORT, 'approval artifacts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_approval_artifacts_delete BEFORE DELETE ON approval_artifacts BEGIN SELECT RAISE(ABORT, 'approval artifacts are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_transitions_update BEFORE UPDATE ON pipeline_transitions BEGIN SELECT RAISE(ABORT, 'pipeline transitions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_transitions_delete BEFORE DELETE ON pipeline_transitions BEGIN SELECT RAISE(ABORT, 'pipeline transitions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_deliveries_update BEFORE UPDATE ON deliveries BEGIN SELECT RAISE(ABORT, 'delivery records are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_deliveries_delete BEFORE DELETE ON deliveries BEGIN SELECT RAISE(ABORT, 'delivery records are immutable'); END;